/**
 * @param {number[][]} grid
 * @return {number}
 */
var uniquePaths = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let res = 0;

    const explore = (i, j, fromLeft) => {
        if (i < 0 || i >= m || j < 0 || j >= n) return;

        if (i === m - 1 && j === n - 1) {
            res++;
            return;
        }

        if (grid[i][j] === 1) {
            if (i === m - 1 && fromLeft) return;
            if (j === n - 1 && !fromLeft) return;

            if (fromLeft) {
                explore(i + 1, j, false);
                return;
            }

            explore(i, j + 1, true);
            return;
        }

        explore(i + 1, j, false);
        explore(i, j + 1, true);
    };

    explore(0, 1, true);
    explore(1, 0, false);

    return res;
};

/** By Leetcode */
var uniquePaths = function (grid) {
    const MOD = 1_000_000_007;
    const m = grid.length;
    const n = grid[0].length;

    const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => [0, 0]));
    dp[0][0][0] = 1;

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (i > 0) {
                if (grid[i - 1][j] === 0) {
                    dp[i][j][0] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % MOD;
                } else {
                    dp[i][j][0] = dp[i - 1][j][1];
                }
            }

            if (j > 0) {
                if (grid[i][j - 1] === 0) {
                    dp[i][j][1] = (dp[i][j - 1][0] + dp[i][j - 1][1]) % MOD;
                } else {
                    dp[i][j][1] = dp[i][j - 1][0];
                }
            }
        }
    }

    return (dp[m - 1][n - 1][0] + dp[m - 1][n - 1][1]) % MOD;
};
